package xray

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/url"
	"strconv"
)

// Parameter keys shared across strategies. Operator-facing (transport) ones
// appear in Params(); Reality keys are generated by the provider and merged in.
// Per-client credentials (uuid/password) live in Client, not Params.
const (
	pPort = "port"
	// pUUID/pPassword are the single-credential keys used only for relay specs
	// (a relay dials with one credential). Instance clients carry their own.
	pUUID        = "uuid"
	pPassword    = "password"
	pSNI         = "sni"          // Reality serverName / TLS SNI
	pDomain      = "domain"       // TLS server cert domain
	pDest        = "dest"         // Reality steal-target host:port
	pRealityPriv = "reality_priv" // base64 x25519 private
	pRealityPub  = "reality_pub"  // base64 x25519 public
	pShortID     = "reality_sid"
	pCertPath    = "cert_path"
	pKeyPath     = "key_path"
	pWSPath      = "ws_path"
	pGRPCService = "grpc_service"
	pSSMethod    = "ss_method"
)

func portOf(p Params, def string) int {
	n, _ := strconv.Atoi(p.get(pPort, def))
	return n
}

func tlsSettings(p Params) map[string]any {
	return map[string]any{
		"serverName": p.get(pDomain, ""),
		"certificates": []any{map[string]any{
			"certificateFile": p.get(pCertPath, "/etc/xray/tls/cert.pem"),
			"keyFile":         p.get(pKeyPath, "/etc/xray/tls/key.pem"),
		}},
	}
}

// VlessClients builds settings.clients for VLESS from the client list.
// Exported for reuse by file-based modules (filemodule.go) whose
// "client_format" is "vless" -- flow is left empty by that path (the most
// broadly compatible option; "xtls-rprx-vision" is specific to raw
// TCP+Reality/TLS-vision and stays a compiled-strategy-only choice).
func VlessClients(clients []Client, flow string) []any {
	out := make([]any, 0, len(clients))
	for _, c := range clients {
		// Xray-core rejects an "encryption" key inside inbound VLESS
		// clients ("VLESS clients: \"encryption\" should not be in
		// inbound settings") -- confirmed live against xray 26.3.27.
		// It only belongs in the outbound/client-link side.
		m := map[string]any{"id": c.UUID}
		if flow != "" {
			m["flow"] = flow
		}
		out = append(out, m)
	}
	return out
}

// VmessClients builds settings.clients for VMess. Exported for reuse by
// file-based modules ("client_format": "vmess").
func VmessClients(clients []Client) []any {
	out := make([]any, 0, len(clients))
	for _, c := range clients {
		out = append(out, map[string]any{"id": c.UUID})
	}
	return out
}

// TrojanClients builds settings.clients for Trojan. Exported for reuse by
// file-based modules ("client_format": "trojan").
func TrojanClients(clients []Client) []any {
	out := make([]any, 0, len(clients))
	for _, c := range clients {
		out = append(out, map[string]any{"password": c.Password})
	}
	return out
}

func vlessLink(uuid, host string, port int, q url.Values, name string) string {
	u := url.URL{Scheme: "vless", User: url.User(uuid), Host: hostPort(host, port), RawQuery: q.Encode(), Fragment: name}
	return u.String()
}

func trojanLink(pw, host string, port int, q url.Values, name string) string {
	u := url.URL{Scheme: "trojan", User: url.User(pw), Host: hostPort(host, port), RawQuery: q.Encode(), Fragment: name}
	return u.String()
}

func hostPort(host string, port int) string { return host + ":" + strconv.Itoa(port) }

func needClients(clients []Client) error {
	if len(clients) == 0 {
		return fmt.Errorf("at least one client is required")
	}
	return nil
}

// ===== 1. VLESS + Reality over TCP =====

type realityVlessTCP struct{}

func (realityVlessTCP) Name() string      { return "reality-vless-tcp" }
func (realityVlessTCP) Label() string     { return "VLESS + Reality (TCP) — max stealth" }
func (realityVlessTCP) Cred() CredKind    { return CredUUID }
func (realityVlessTCP) MultiClient() bool { return true }
func (realityVlessTCP) InstanceSecrets() []SecretSpec {
	return []SecretSpec{
		{Key: pRealityPriv, Kind: "reality_keypair", PairKey: pRealityPub},
		{Key: pShortID, Kind: "short_id"},
	}
}
func (realityVlessTCP) Params() []ParamSpec {
	return []ParamSpec{
		{Key: pPort, Label: "Listen port", Default: "443", Required: true},
		{Key: pSNI, Label: "Camouflage SNI (real TLS site)", Placeholder: "www.microsoft.com", Required: true},
		{Key: pDest, Label: "Steal-from target host:port", Placeholder: "www.microsoft.com:443", Required: true},
	}
}
func (realityVlessTCP) BuildInbound(p Params, clients []Client) (map[string]any, error) {
	if err := requireParams(p, realityVlessTCP{}.Params()); err != nil {
		return nil, err
	}
	if err := needClients(clients); err != nil {
		return nil, err
	}
	if p.get(pRealityPriv, "") == "" {
		return nil, fmt.Errorf("reality private key must be provisioned")
	}
	return map[string]any{
		"listen":   "0.0.0.0",
		"port":     portOf(p, "443"),
		"protocol": "vless",
		"settings": map[string]any{"clients": VlessClients(clients, "xtls-rprx-vision"), "decryption": "none"},
		"streamSettings": map[string]any{
			"network":  "tcp",
			"security": "reality",
			"realitySettings": map[string]any{
				"show":        false,
				"dest":        p.get(pDest, ""),
				"serverNames": []any{p.get(pSNI, "")},
				"privateKey":  p.get(pRealityPriv, ""),
				"shortIds":    []any{p.get(pShortID, "")},
			},
		},
	}, nil
}
func (realityVlessTCP) ClientLink(p Params, c Client, host string) (string, error) {
	if p.get(pRealityPub, "") == "" {
		return "", fmt.Errorf("reality public key missing")
	}
	q := url.Values{}
	q.Set("security", "reality")
	q.Set("encryption", "none")
	q.Set("type", "tcp")
	q.Set("sni", p.get(pSNI, ""))
	q.Set("fp", "chrome")
	q.Set("pbk", p.get(pRealityPub, ""))
	q.Set("sid", p.get(pShortID, ""))
	q.Set("flow", "xtls-rprx-vision")
	return vlessLink(c.UUID, host, portOf(p, "443"), q, linkName(c, host)), nil
}

// ===== 2. VLESS + XTLS-Vision over TLS =====

type vlessVisionTLS struct{}

func (vlessVisionTLS) Name() string      { return "vless-vision-tls" }
func (vlessVisionTLS) Label() string     { return "VLESS + Vision (TLS)" }
func (vlessVisionTLS) Cred() CredKind    { return CredUUID }
func (vlessVisionTLS) MultiClient() bool { return true }
func (vlessVisionTLS) Params() []ParamSpec {
	return []ParamSpec{
		{Key: pPort, Label: "Listen port", Default: "443", Required: true},
		{Key: pDomain, Label: "TLS domain (your cert)", Placeholder: "vpn.example.com", Required: true},
		{Key: pCertPath, Label: "Cert file path", Default: "/etc/xray/tls/cert.pem"},
		{Key: pKeyPath, Label: "Key file path", Default: "/etc/xray/tls/key.pem"},
	}
}
func (vlessVisionTLS) BuildInbound(p Params, clients []Client) (map[string]any, error) {
	if err := requireParams(p, vlessVisionTLS{}.Params()); err != nil {
		return nil, err
	}
	if err := needClients(clients); err != nil {
		return nil, err
	}
	return map[string]any{
		"listen":   "0.0.0.0",
		"port":     portOf(p, "443"),
		"protocol": "vless",
		"settings": map[string]any{"clients": VlessClients(clients, "xtls-rprx-vision"), "decryption": "none"},
		"streamSettings": map[string]any{
			"network":     "tcp",
			"security":    "tls",
			"tlsSettings": tlsSettings(p),
		},
	}, nil
}
func (vlessVisionTLS) ClientLink(p Params, c Client, host string) (string, error) {
	q := url.Values{}
	q.Set("security", "tls")
	q.Set("encryption", "none")
	q.Set("type", "tcp")
	q.Set("sni", p.get(pDomain, host))
	q.Set("flow", "xtls-rprx-vision")
	return vlessLink(c.UUID, p.get(pDomain, host), portOf(p, "443"), q, linkName(c, host)), nil
}

// ===== 3. VMess + WebSocket + TLS (CDN) =====

type vmessWSTLS struct{}

func (vmessWSTLS) Name() string      { return "vmess-ws-tls" }
func (vmessWSTLS) Label() string     { return "VMess + WebSocket + TLS (CDN)" }
func (vmessWSTLS) Cred() CredKind    { return CredUUID }
func (vmessWSTLS) MultiClient() bool { return true }
func (vmessWSTLS) Params() []ParamSpec {
	return []ParamSpec{
		{Key: pPort, Label: "Listen port", Default: "443", Required: true},
		{Key: pDomain, Label: "TLS domain", Placeholder: "cdn.example.com", Required: true},
		{Key: pWSPath, Label: "WebSocket path", Default: "/ws"},
		{Key: pCertPath, Label: "Cert file path", Default: "/etc/xray/tls/cert.pem"},
		{Key: pKeyPath, Label: "Key file path", Default: "/etc/xray/tls/key.pem"},
	}
}
func (vmessWSTLS) BuildInbound(p Params, clients []Client) (map[string]any, error) {
	if err := requireParams(p, vmessWSTLS{}.Params()); err != nil {
		return nil, err
	}
	if err := needClients(clients); err != nil {
		return nil, err
	}
	return map[string]any{
		"listen":   "0.0.0.0",
		"port":     portOf(p, "443"),
		"protocol": "vmess",
		"settings": map[string]any{"clients": VmessClients(clients)},
		"streamSettings": map[string]any{
			"network":     "ws",
			"security":    "tls",
			"wsSettings":  map[string]any{"path": p.get(pWSPath, "/ws")},
			"tlsSettings": tlsSettings(p),
		},
	}, nil
}
func (vmessWSTLS) ClientLink(p Params, c Client, host string) (string, error) {
	domain := p.get(pDomain, host)
	conf := map[string]any{
		"v": "2", "ps": linkName(c, host), "add": domain, "port": strconv.Itoa(portOf(p, "443")),
		"id": c.UUID, "aid": "0", "scy": "auto", "net": "ws", "type": "none",
		"host": domain, "path": p.get(pWSPath, "/ws"), "tls": "tls", "sni": domain,
	}
	b, err := json.Marshal(conf)
	if err != nil {
		return "", err
	}
	return "vmess://" + base64.StdEncoding.EncodeToString(b), nil
}

