type trojanTCPTLS struct{}

func (trojanTCPTLS) Name() string      { return "trojan-tcp-tls" }
func (trojanTCPTLS) Label() string     { return "Trojan (TLS)" }
func (trojanTCPTLS) Cred() CredKind    { return CredPassword }
func (trojanTCPTLS) MultiClient() bool { return true }
func (trojanTCPTLS) Params() []ParamSpec {
	return []ParamSpec{
		{Key: pPort, Label: "Listen port", Default: "443", Required: true},
		{Key: pDomain, Label: "TLS domain", Placeholder: "vpn.example.com", Required: true},
		{Key: pCertPath, Label: "Cert file path", Default: "/etc/xray/tls/cert.pem"},
		{Key: pKeyPath, Label: "Key file path", Default: "/etc/xray/tls/key.pem"},
	}
}
func (trojanTCPTLS) BuildInbound(p Params, clients []Client) (map[string]any, error) {
	if err := requireParams(p, trojanTCPTLS{}.Params()); err != nil {
		return nil, err
	}
	if err := needClients(clients); err != nil {
		return nil, err
	}
	return map[string]any{
		"listen":   "0.0.0.0",
		"port":     portOf(p, "443"),
		"protocol": "trojan",
		"settings": map[string]any{"clients": TrojanClients(clients)},
		"streamSettings": map[string]any{
			"network":     "tcp",
			"security":    "tls",
			"tlsSettings": tlsSettings(p),
		},
	}, nil
}
