// ===== 5. Shadowsocks 2022 (single client) =====

type shadowsocks2022 struct{}

func (shadowsocks2022) Name() string      { return "shadowsocks-2022" }
func (shadowsocks2022) Label() string     { return "Shadowsocks 2022 (single client)" }
func (shadowsocks2022) Cred() CredKind    { return CredPassword }
func (shadowsocks2022) MultiClient() bool { return false }
func (shadowsocks2022) Params() []ParamSpec {
	return []ParamSpec{
		{Key: pPort, Label: "Listen port", Default: "8388", Required: true},
		{Key: pSSMethod, Label: "Cipher", Default: "2022-blake3-aes-128-gcm"},
	}
}
func (shadowsocks2022) BuildInbound(p Params, clients []Client) (map[string]any, error) {
	if err := requireParams(p, shadowsocks2022{}.Params()); err != nil {
		return nil, err
	}
	if err := needClients(clients); err != nil {
		return nil, err
	}
	return map[string]any{
		"listen":   "0.0.0.0",
		"port":     portOf(p, "8388"),
		"protocol": "shadowsocks",
		"settings": map[string]any{
			"method":   p.get(pSSMethod, "2022-blake3-aes-128-gcm"),
			"password": clients[0].Password,
			"network":  "tcp,udp",
		},
	}, nil
}
func (shadowsocks2022) ClientLink(p Params, c Client, host string) (string, error) {
	method := p.get(pSSMethod, "2022-blake3-aes-128-gcm")
	userinfo := base64.RawURLEncoding.EncodeToString([]byte(method + ":" + c.Password))
	return fmt.Sprintf("ss://%s@%s#%s", userinfo, hostPort(host, portOf(p, "8388")), linkName(c, host)), nil
}

// ===== 6. VLESS + gRPC + TLS =====

type vlessGRPCTLS struct{}

func (vlessGRPCTLS) Name() string      { return "vless-grpc-tls" }
func (vlessGRPCTLS) Label() string     { return "VLESS + gRPC + TLS" }
func (vlessGRPCTLS) Cred() CredKind    { return CredUUID }
func (vlessGRPCTLS) MultiClient() bool { return true }
func (vlessGRPCTLS) Params() []ParamSpec {
	return []ParamSpec{
		{Key: pPort, Label: "Listen port", Default: "443", Required: true},
		{Key: pDomain, Label: "TLS domain", Placeholder: "vpn.example.com", Required: true},
		{Key: pGRPCService, Label: "gRPC service name", Default: "grpc"},
		{Key: pCertPath, Label: "Cert file path", Default: "/etc/xray/tls/cert.pem"},
		{Key: pKeyPath, Label: "Key file path", Default: "/etc/xray/tls/key.pem"},
	}
}
func (vlessGRPCTLS) BuildInbound(p Params, clients []Client) (map[string]any, error) {
	if err := requireParams(p, vlessGRPCTLS{}.Params()); err != nil {
		return nil, err
	}
	if err := needClients(clients); err != nil {
		return nil, err
	}
	return map[string]any{
		"listen":   "0.0.0.0",
		"port":     portOf(p, "443"),
		"protocol": "vless",
		"settings": map[string]any{"clients": VlessClients(clients, ""), "decryption": "none"},
		"streamSettings": map[string]any{
			"network":      "grpc",
			"security":     "tls",
			"grpcSettings": map[string]any{"serviceName": p.get(pGRPCService, "grpc")},
			"tlsSettings":  tlsSettings(p),
		},
	}, nil
}
func (vlessGRPCTLS) ClientLink(p Params, c Client, host string) (string, error) {
	q := url.Values{}
	q.Set("security", "tls")
	q.Set("encryption", "none")
	q.Set("type", "grpc")
	q.Set("serviceName", p.get(pGRPCService, "grpc"))
	q.Set("sni", p.get(pDomain, host))
	return vlessLink(c.UUID, p.get(pDomain, host), portOf(p, "443"), q, linkName(c, host)), nil
}

func linkName(c Client, host string) string {
	if c.Name != "" {
		return c.Name
	}
	return host
}

func init() {
	Register(realityVlessTCP{})
	Register(vlessVisionTLS{})
	Register(vmessWSTLS{})
	Register(trojanTCPTLS{})
	Register(shadowsocks2022{})
	Register(vlessGRPCTLS{})
}
